    /// Контур буквы в координатах рамки
    static func path(_ index: Int) -> Path {
        var p = Path()
        for sub in data[index] where sub.count >= 6 {
            p.move(to: CGPoint(x: sub[0], y: sub[1]))
            var i = 2
            while i + 1 < sub.count {
                p.addLine(to: CGPoint(x: sub[i], y: sub[i + 1]))
                i += 2
            }
            p.closeSubpath()
        }
        return p
    }
